// Slack 메시지에서 GitLab ↔ Redmine 이슈 번호 쌍 추출 + 중복 제거
const messages = $input.item.json.messages || [];
const issuePairs = [];

// 중복 확인용 Set (gitlabId-redmineId 형식으로 저장)
const seen = new Set();

for (const message of messages) {
  if (!message.text) continue;

  // GitLab ID 추출
  const gitlabMatch = message.text.match(/https:\/\/[^ ]+\/issues\/(\d+)/);
  const gitlabId = gitlabMatch ? parseInt(gitlabMatch[1]) : null;

  // Redmine ID 추출
  const redmineMatch = message.text.match(/https:\/\/rm\.evolvesoft\.cf\/issues\/(\d+)/);
  const redmineId = redmineMatch ? parseInt(redmineMatch[1]) : null;

  if (gitlabId && redmineId) {
    const key = `${gitlabId}-${redmineId}`;
    if (!seen.has(key)) {
      seen.add(key);
      issuePairs.push({
        json: {
          gitlabId,
          redmineId
        }
      });
    }
  }
}

return issuePairs;

if (!$input.all() || $input.all().length === 0) {
  return [];
}

const inputData = $input.all()[0].json;
const issues = inputData.issues || [];

if (issues.length === 0) {
  return [];
}

const processedIssues = issues.map(issue => {
  const journals = issue.journals || [];
  const lastJournal = journals.length > 0 ? journals[journals.length - 1] : null;

  let changeType = 'updated';

  const createdAt = new Date(issue.created_on || issue.created_at);
  const updatedAt = new Date(issue.updated_on || issue.updated_at);
  const timeDiff = Math.abs(updatedAt - createdAt);

  if (timeDiff < 60000) {
    changeType = 'created';
  } else if (lastJournal && lastJournal.details) {
    const details = lastJournal.details || [];
    const statusChange = details.find(d => d.name === 'status_id');

    if (statusChange && (statusChange.new_value === '5' || statusChange.new_value === '6')) {
      changeType = 'closed';
    }
  }

  return {
    redmine_issue: issue,
    changeType,
    timestamp: issue.updated_on || issue.updated_at
  };
});

return processedIssues.map(item => ({ json: item }));

const itemsToCheck = $items("메시지 필터링");

const gitlabIssues = $items("GitLab 이슈 조회1");
const redmineIssues = $items("Redmine 변경 유형 분석");

let results = [];

itemsToCheck.forEach(({ json: { gitlabId, redmineId } }) => {
  const gitlabIssue = gitlabIssues.find(item => item.json.iid === gitlabId)?.json;
  const redmineIssue = redmineIssues.find(item => item.json.redmine_issue?.id === redmineId)?.json.redmine_issue;

  if (!gitlabIssue || !redmineIssue) {
    results.push({
      gitlabId,
      redmineId,
      error: 'GitLab 또는 Redmine 이슈를 찾을 수 없습니다.',
      action: 'skip'
    });
    return;
  }

  if (gitlabIssue.state === "opened" && (redmineIssue.status?.name === "거절" || redmineIssue.status?.name === "완료")) {
    results.push({
      gitlabId,
      redmineId,
      action: 'close'
    });
    return;
  }

  if (redmineIssue.closed_on) {
    results.push({
      gitlabId,
      redmineId,
      action: 'skip',
      reason: 'Redmine 이슈가 종료(closed_on) 상태입니다.'
    });
    return;
  }

  const fieldsToCompare = ['title', 'description', 'due_date'];
  let changes = {};

  fieldsToCompare.forEach(field => {
    const oldValue = gitlabIssue[field] != null ? String(gitlabIssue[field]).trim() : '';
    let newValue = '';

    if (field === 'title') {
      newValue = redmineIssue.subject ? String(redmineIssue.subject).trim() : '';
    } else {
      newValue = redmineIssue[field] != null ? String(redmineIssue[field]).trim() : '';
    }

    if (oldValue !== newValue) {
      changes[field] = newValue;
    }
  });

  if (Object.keys(changes).length === 0) {
    results.push({
      gitlabId,
      redmineId,
      action: 'skip'
    });
  } else {
    results.push({
      gitlabId,
      redmineId,
      action: 'update',
      updateData: {
        ...changes,
        labels: ['new', 'redmine-sync'],
        state_event: 'reopen',
      }
    });
  }
});

const filteredResults = results.filter(item => item.action === 'update');
return filteredResults.map(item => ({ json: item }));

